1. Registry Monitoring:
```csharp
using System.Windows.Forms;
using System.IO;
using System.Threading;

public class RegistryMonitor : IDisposable
{
    private readonly Dictionary<string, string> _registryChanges = new Dictionary<string, string>();
    private readonly Timer _timer;

    public RegistryMonitor()
    {
        _timer = new Timer(CheckRegistryChanges, null, TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(1));
    }

    private void CheckRegistryChanges(object state)
    {
        var key = Registry.LocalMachine.OpenSubKey("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Explorer");
        if (key != null)
        {
            var changes = key.GetSubKeyNames();
            foreach (var change in changes)
            {
                var value = key.GetValue(change);
                if (value != null && value.ToString() != _registryChanges[change])
                {
                    _registryChanges[change] = value.ToString();
                    OnRegistryChange(change);
                }
            }
        }
    }

    public event Action OnRegistryChange;

    public void Dispose()
    {
        _timer.Dispose();
    }
}
```
2. File Monitoring:
```csharp
using System.IO;
using System.Threading;

public class FileMonitor : IDisposable
{
    private readonly Dictionary<string, string> _fileChanges = new Dictionary<string, string>();
    private readonly Timer _timer;

    public FileMonitor()
    {
        _timer = new Timer(CheckFileChanges, null, TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(1));
    }

    private void CheckFileChanges(object state)
    {
        var filePath = "C:\\Users\\User\\AppData\\Local\\Microsoft\\Windows\\Explorer";
        var file = new FileInfo(filePath);
        if (file.Exists)
        {
            var changes = file.GetFileSystemEntries();
            foreach (var change in changes)
            {
                var name = change.Name;
                var value = change.Value;
                if (value != _fileChanges[name])
                {
                    _fileChanges[name] = value;
                    OnFileChange(name);
                }
            }
        }
    }

    public event Action OnFileChange;

    public void Dispose()
    {
        _timer.Dispose();
    }
}
```
